cocktail.java:
static void cocktail(int[] a) {
    int lo = 0;
    int hi = a.length - 1;
    boolean swapped = true;
    while (swapped && lo < hi) {
        swapped = false;
        for (int i = lo; i < hi; i++) {
            if (a[i] > a[i + 1]) {
                swap(a, i, i + 1);
                swapped = true;
            }
        }
        hi--;
        for (int i = hi; i > lo; i--) {
            if (a[i - 1] > a[i]) {
                swap(a, i - 1, i);
                swapped = true;
            }
        }
        lo++;
    }
}

