static void oddEven(int[] a) {
    boolean sorted = false;
    while (!sorted) {
        sorted = true;
        for (int start = 1; start >= 0; start--) {
            for (int i = start; i + 1 < a.length; i += 2) {
                if (a[i] > a[i + 1]) {
                    swap(a, i, i + 1);
                    sorted = false;
                }
            }
        }
    }
}

