static void comb(int[] a) {
    int gap = a.length;
    boolean swapped = true;
    while (gap > 1 || swapped) {
        gap = Math.max(1, div(gap * 10, 13));
        swapped = false;
        for (int i = 0; i + gap < a.length; i++) {
            if (a[i] > a[i + gap]) {
                swap(a, i, i + gap);
                swapped = true;
            }
        }
    }
}

