doubleSelection.java:
static void doubleSelection(int[] a) {
    int lo = 0;
    int hi = a.length - 1;
    while (lo < hi) {
        int min = lo;
        int max = lo;
        for (int i = lo + 1; i <= hi; i++) {
            if (a[i] < a[min]) {
                min = i;
            }
            if (a[i] > a[max]) {
                max = i;
            }
        }
        swap(a, lo, min);
        // The largest may have just been moved by that swap.
        if (max == lo) {
            max = min;
        }
        swap(a, hi, max);
        lo++;
        hi--;
    }
}

