bingo.java:
static void bingo(int[] a) {
    if (a.length < 2) {
        return;
    }
    int top = maxOf(a);
    int target = minOf(a);
    int placed = 0;
    while (target < top) {
        int next = top;
        for (int i = placed; i < a.length; i++) {
            if (a[i] == target) {
                swap(a, i, placed);
                placed++;
            } else if (a[i] < next) {
                next = a[i];
            }
        }
        target = next;
    }
}

