cycle.java:
static void cycle(int[] a) {
    int n = a.length;
    for (int start = 0; start < n - 1; start++) {
        int item = a[start];
        int pos = start;
        for (int i = start + 1; i < n; i++) {
            if (a[i] < item) {
                pos++;
            }
        }
        if (pos == start) {
            continue;
        }
        while (item == a[pos]) {
            pos++;
        }
        int held = a[pos];
        a[pos] = item;
        item = held;
        while (pos != start) {
            pos = start;
            for (int i = start + 1; i < n; i++) {
                if (a[i] < item) {
                    pos++;
                }
            }
            while (item == a[pos]) {
                pos++;
            }
            held = a[pos];
            a[pos] = item;
            item = held;
        }
    }
}

