static void pancake(int[] a) {
    for (int size = a.length; size > 1; size--) {
        int max = 0;
        for (int i = 1; i < size; i++) {
            if (a[i] > a[max]) {
                max = i;
            }
        }
        if (max != size - 1) {
            reverse(a, 0, max);
            reverse(a, 0, size - 1);
        }
    }
}

