static void insertion(int[] a) {
    insertionRange(a, 0, a.length - 1);
}

/** Sorts a[lo..hi], both ends included. */
static void insertionRange(int[] a, int lo, int hi) {
    for (int i = lo + 1; i <= hi; i++) {
        int x = a[i];
        int j = i - 1;
        while (j >= lo && a[j] > x) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = x;
    }
}

