shell.java:
static void shell(int[] a) {
    for (int gap = a.length >> 1; gap > 0; gap >>= 1) {
        gapInsertion(a, gap);
    }
}

private static void gapInsertion(int[] a, int gap) {
    for (int i = gap; i < a.length; i++) {
        int x = a[i];
        int j = i;
        while (j >= gap && a[j - gap] > x) {
            a[j] = a[j - gap];
            j -= gap;
        }
        a[j] = x;
    }
}

