static void mergeBottomUp(int[] a) {
    int n = a.length;
    int[] aux = new int[n];
    for (int width = 1; width < n; width *= 2) {
        for (int lo = 0; lo + width < n; lo += 2 * width) {
            merge(a, aux, lo, lo + width - 1, Math.min(lo + 2 * width - 1, n - 1));
        }
    }
}

