static void merge(int[] a, int[] aux, int lo, int mid, int hi) {
    arraycopy(a, lo, aux, lo, mid - lo + 1);
    int i = lo;
    int j = mid + 1;
    int k = lo;
    while (i <= mid && j <= hi) {
        if (aux[i] <= a[j]) {
            a[k] = aux[i];
            i++;
        } else {
            a[k] = a[j];
            j++;
        }
        k++;
    }
    while (i <= mid) {
        a[k] = aux[i];
        i++;
        k++;
    }
}

private static int extendRun(int[] a, int lo) {
    int run = countRun(a, lo);
    int forced = Math.min(16, a.length - lo);
    if (run < forced) {
        binaryInsertRange(a, lo, lo + forced, lo + run);
        return forced;
    }
    return run;
}

/** Depth of the boundary between two runs in a perfectly balanced tree over the array. */
private static int nodePower(int n, int lo, int run, int next) {
    double x = (lo + run / 2.0) / n;
    double y = (lo + run + next / 2.0) / n;
    for (int power = 1; ; power++) {
        x *= 2;
        y *= 2;
        if ((int) x != (int) y) {
            return power;
        }
        if (x >= 1) {
            x -= 1;
            y -= 1;
        }
    }
}

static void tree(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int[] key = new int[n + 1];
    int[] left = new int[n + 1];
    int[] right = new int[n + 1];
    key[1] = a[0];
    for (int i = 2; i <= n; i++) {
        key[i] = a[i - 1];
        int node = 1;
        while (true) {
            if (key[i] < key[node]) {
                if (left[node] == 0) {
                    left[node] = i;
                    break;
                }
                node = left[node];
            } else {
                if (right[node] == 0) {
                    right[node] = i;
                    break;
                }
                node = right[node];
            }
        }
    }
    readInOrder(key, left, right, 1, a);
}

/** Sorts a[lo..hi) when a[lo..start) is already sorted. */
static void binaryInsertRange(int[] a, int lo, int hi, int start) {
    for (int i = start; i < hi; i++) {
        int x = a[i];
        int left = lo;
        int right = i;
        while (left < right) {
            int mid = (left + right) >>> 1;
            if (a[mid] <= x) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        arraycopy(a, left, a, left + 1, i - left);
        a[left] = x;
    }
}

/** Length of the run starting at lo, reversing it first if it descends. */
private static int countRun(int[] a, int lo) {
    int n = a.length;
    int hi = lo + 1;
    if (hi == n) {
        return 1;
    }
    if (a[hi] < a[lo]) {
        hi++;
        while (hi < n && a[hi] < a[hi - 1]) {
            hi++;
        }
        reverse(a, lo, hi - 1);
    } else {
        hi++;
        while (hi < n && a[hi] >= a[hi - 1]) {
            hi++;
        }
    }
    return hi - lo;
}

/** Walks the tree in order with an explicit stack, because a tree can be n levels deep. */
private static void readInOrder(int[] key, int[] left, int[] right, int root, int[] out) {
    int[] stack = new int[out.length + 1];
    int top = 0;
    int node = root;
    int k = 0;
    while (node != 0 || top > 0) {
        while (node != 0) {
            stack[top] = node;
            top++;
            node = left[node];
        }
        top--;
        node = stack[top];
        out[k] = key[node];
        k++;
        node = right[node];
    }
}

