static void patience(int[] a) {
    int n = a.length;
    int[] card = copy(a);
    int[] below = new int[n];
    int[] top = new int[n];
    int piles = 0;
    for (int i = 0; i < n; i++) {
        // Deal onto the leftmost pile whose top card is not smaller.
        int lo = 0;
        int hi = piles;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (card[top[mid]] >= card[i]) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        below[i] = lo < piles ? top[lo] : -1;
        top[lo] = i;
        if (lo == piles) {
            piles++;
        }
    }
    // The pile tops rise from left to right, so they're already a valid heap.
    for (int k = 0; k < n; k++) {
        int next = top[0];
        a[k] = card[next];
        if (below[next] >= 0) {
            top[0] = below[next];
        } else {
            piles--;
            top[0] = top[piles];
        }
        int i = 0;
        while (true) {
            int child = 2 * i + 1;
            if (child >= piles) {
                break;
            }
            if (child + 1 < piles && card[top[child + 1]] < card[top[child]]) {
                child++;
            }
            if (card[top[child]] >= card[top[i]]) {
                break;
            }
            swap(top, i, child);
            i = child;
        }
    }
}

static void heap(int[] a) {
    heapRange(a, 0, a.length - 1);
}

/** Sorts a[lo..hi], both ends included. */
static void heapRange(int[] a, int lo, int hi) {
    int n = hi - lo + 1;
    for (int i = (n >> 1) - 1; i >= 0; i--) {
        siftDown(a, lo, i, n);
    }
    for (int end = n - 1; end > 0; end--) {
        swap(a, lo, lo + end);
        siftDown(a, lo, 0, end);
    }
}

private static void siftDown(int[] a, int lo, int i, int n) {
    int x = a[lo + i];
    while (true) {
        int child = 2 * i + 1;
        if (child >= n) {
            break;
        }
        if (child + 1 < n && a[lo + child + 1] > a[lo + child]) {
            child++;
        }
        if (a[lo + child] <= x) {
            break;
        }
        a[lo + i] = a[lo + child];
        i = child;
    }
    a[lo + i] = x;
}

