static void tournament(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int leaves = 1;
    while (leaves < n) {
        leaves *= 2;
    }
    int[] player = copy(a);
    int[] tree = new int[2 * leaves];
    for (int i = 0; i < leaves; i++) {
        tree[leaves + i] = i < n ? i : -1;
    }
    for (int i = leaves - 1; i >= 1; i--) {
        tree[i] = winner(player, tree[2 * i], tree[2 * i + 1]);
    }
    for (int k = 0; k < n; k++) {
        int champion = tree[1];
        a[k] = player[champion];
        int node = leaves + champion;
        tree[node] = -1;
        node >>= 1;
        while (node >= 1) {
            tree[node] = winner(player, tree[2 * node], tree[2 * node + 1]);
            node >>= 1;
        }
    }
}

private static int winner(int[] player, int x, int y) {
    if (x < 0) {
        return y;
    }
    if (y < 0) {
        return x;
    }
    return player[y] < player[x] ? y : x;
}

static void tree(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int[] key = new int[n + 1];
    int[] left = new int[n + 1];
    int[] right = new int[n + 1];
    key[1] = a[0];
    for (int i = 2; i <= n; i++) {
        key[i] = a[i - 1];
        int node = 1;
        while (true) {
            if (key[i] < key[node]) {
                if (left[node] == 0) {
                    left[node] = i;
                    break;
                }
                node = left[node];
            } else {
                if (right[node] == 0) {
                    right[node] = i;
                    break;
                }
                node = right[node];
            }
        }
    }
    readInOrder(key, left, right, 1, a);
}

/** Walks the tree in order with an explicit stack, because a tree can be n levels deep. */
private static void readInOrder(int[] key, int[] left, int[] right, int root, int[] out) {
    int[] stack = new int[out.length + 1];
    int top = 0;
    int node = root;
    int k = 0;
    while (node != 0 || top > 0) {
        while (node != 0) {
            stack[top] = node;
            top++;
            node = left[node];
        }
        top--;
        node = stack[top];
        out[k] = key[node];
        k++;
        node = right[node];
    }
}

