static void quickLomuto(int[] a) {
    lomutoRange(a, 0, a.length - 1);
}

private static void lomutoRange(int[] a, int lo, int hi) {
    while (lo < hi) {
        int pivot = a[hi];
        int p = lo;
        for (int i = lo; i < hi; i++) {
            if (a[i] < pivot) {
                swap(a, i, p);
                p++;
            }
        }
        swap(a, p, hi);
        if (p - lo < hi - p) {
            lomutoRange(a, lo, p - 1);
            lo = p + 1;
        } else {
            lomutoRange(a, p + 1, hi);
            hi = p - 1;
        }
    }
}

