private static void hoareRange(int[] a, int lo, int hi) {
    while (lo < hi) {
        int pivot = a[(lo + hi) >>> 1];
        int i = lo;
        int j = hi;
        while (i <= j) {
            while (a[i] < pivot) {
                i++;
            }
            while (a[j] > pivot) {
                j--;
            }
            if (i <= j) {
                swap(a, i, j);
                i++;
                j--;
            }
        }
        if (j - lo < hi - i) {
            hoareRange(a, lo, j);
            lo = i;
        } else {
            hoareRange(a, i, hi);
            hi = j;
        }
    }
}

