static void quickDualPivot(int[] a) {
    dualPivotRange(a, 0, a.length - 1);
}

private static void dualPivotRange(int[] a, int lo, int hi) {
    while (lo < hi) {
        int third = div(hi - lo, 3);
        swap(a, lo, lo + third);
        swap(a, hi, hi - third);
        if (a[lo] > a[hi]) {
            swap(a, lo, hi);
        }
        int small = a[lo];
        int large = a[hi];
        int lt = lo + 1;
        int gt = hi - 1;
        int i = lt;
        while (i <= gt) {
            if (a[i] < small) {
                swap(a, i, lt);
                lt++;
                i++;
            } else if (a[i] > large) {
                swap(a, i, gt);
                gt--;
            } else {
                i++;
            }
        }
        lt--;
        gt++;
        swap(a, lo, lt);
        swap(a, hi, gt);
        int left = lt - lo;
        int middle = gt - lt;
        int right = hi - gt;
        if (left >= middle && left >= right) {
            dualPivotRange(a, lt + 1, gt - 1);
            dualPivotRange(a, gt + 1, hi);
            hi = lt - 1;
        } else if (middle >= right) {
            dualPivotRange(a, lo, lt - 1);
            dualPivotRange(a, gt + 1, hi);
            lo = lt + 1;
            hi = gt - 1;
        } else {
            dualPivotRange(a, lo, lt - 1);
            dualPivotRange(a, lt + 1, gt - 1);
            lo = gt + 1;
        }
    }
}

