static void introsort(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    introRange(a, 0, n - 1, 2 * (31 - clz(n)));
    insertionRange(a, 0, n - 1);
}

/** Sorts a[lo..hi], both ends included. */
static void insertionRange(int[] a, int lo, int hi) {
    for (int i = lo + 1; i <= hi; i++) {
        int x = a[i];
        int j = i - 1;
        while (j >= lo && a[j] > x) {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = x;
    }
}

/** Quicksort until ranges are tiny, or heapsort if the pivots keep going badly. */
private static void introRange(int[] a, int lo, int hi, int depth) {
    while (hi - lo > 16) {
        if (depth == 0) {
            heapRange(a, lo, hi);
            return;
        }
        depth--;
        int mid = (lo + hi) >>> 1;
        int pivot = Math.max(Math.min(a[lo], a[mid]), Math.min(Math.max(a[lo], a[mid]), a[hi]));
        int i = lo - 1;
        int j = hi + 1;
        while (true) {
            do {
                i++;
            } while (a[i] < pivot);
            do {
                j--;
            } while (a[j] > pivot);
            if (i >= j) {
                break;
            }
            swap(a, i, j);
        }
        introRange(a, j + 1, hi, depth);
        hi = j;
    }
}

/** Sorts a[lo..hi], both ends included. */
static void heapRange(int[] a, int lo, int hi) {
    int n = hi - lo + 1;
    for (int i = (n >> 1) - 1; i >= 0; i--) {
        siftDown(a, lo, i, n);
    }
    for (int end = n - 1; end > 0; end--) {
        swap(a, lo, lo + end);
        siftDown(a, lo, 0, end);
    }
}

private static void siftDown(int[] a, int lo, int i, int n) {
    int x = a[lo + i];
    while (true) {
        int child = 2 * i + 1;
        if (child >= n) {
            break;
        }
        if (child + 1 < n && a[lo + child + 1] > a[lo + child]) {
            child++;
        }
        if (a[lo + child] <= x) {
            break;
        }
        a[lo + i] = a[lo + child];
        i = child;
    }
    a[lo + i] = x;
}

