static void heapTernary(int[] a) {
    int n = a.length;
    for (int i = div(n - 2, 3); i >= 0 && n > 1; i--) {
        ternaryDown(a, i, n);
    }
    for (int end = n - 1; end > 0; end--) {
        swap(a, 0, end);
        ternaryDown(a, 0, end);
    }
}

private static void ternaryDown(int[] a, int i, int n) {
    int x = a[i];
    while (true) {
        int first = 3 * i + 1;
        if (first >= n) {
            break;
        }
        int child = first;
        int stop = Math.min(first + 3, n);
        for (int c = first + 1; c < stop; c++) {
            if (a[c] > a[child]) {
                child = c;
            }
        }
        if (a[child] <= x) {
            break;
        }
        a[i] = a[child];
        i = child;
    }
    a[i] = x;
}

