static void heapWeak(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    boolean[] flipped = new boolean[n];
    for (int i = n - 1; i > 0; i--) {
        int j = i;
        while ((j & 1) == (flipped[j >> 1] ? 1 : 0)) {
            j >>= 1;
