    for (int end = n - 1; end >= 2; end--) {
        swap(a, 0, end);
        int x = 1;
        int y = 2 * x + (flipped[x] ? 1 : 0);
        while (y < end) {
            x = y;
            y = 2 * x + (flipped[x] ? 1 : 0);
