/** Dijkstra's smoothsort: a forest of Leonardo heaps, so sorted input costs O(n). */
static void smooth(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int[] size = new int[44];
    size[0] = 1;
    size[1] = 1;
    for (int i = 2; i < 44; i++) {
        size[i] = size[i - 1] + size[i - 2] + 1;
    }
    int[] orders = new int[64];
    int trees = 0;
    for (int i = 0; i < n; i++) {
        if (trees >= 2 && orders[trees - 2] == orders[trees - 1] + 1) {
            trees--;
            orders[trees - 1]++;
        } else if (trees >= 1 && orders[trees - 1] == 1) {
            orders[trees] = 0;
            trees++;
        } else {
            orders[trees] = 1;
            trees++;
        }
        fixRoots(a, size, orders, trees - 1, i);
    }
    for (int i = n - 1; i > 0; i--) {
        trees--;
        int order = orders[trees];
        if (order >= 2) {
            int right = i - 1;
            int left = right - size[order - 2];
            orders[trees] = order - 1;
            trees++;
            fixRoots(a, size, orders, trees - 1, left);
            orders[trees] = order - 2;
            trees++;
            fixRoots(a, size, orders, trees - 1, right);
        }
    }
}

/** Keeps tree roots rising from left to right, then repairs the tree the new root landed in. */
private static void fixRoots(int[] a, int[] size, int[] orders, int tree, int root) {
    while (tree > 0) {
        int previous = root - size[orders[tree]];
        if (a[previous] <= a[root]) {
            break;
        }
        int order = orders[tree];
        if (order >= 2) {
            int right = root - 1;
            int left = right - size[order - 2];
            if (a[previous] <= a[right] || a[previous] <= a[left]) {
                break;
            }
        }
        swap(a, previous, root);
        root = previous;
        tree--;
    }
    siftLeonardo(a, size, root, orders[tree]);
}

private static void siftLeonardo(int[] a, int[] size, int root, int order) {
    while (order >= 2) {
        int right = root - 1;
        int left = right - size[order - 2];
        int child = a[left] >= a[right] ? left : right;
        if (a[root] >= a[child]) {
            return;
        }
        swap(a, root, child);
        order = child == left ? order - 1 : order - 2;
        root = child;
    }
}

static void tree(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int[] key = new int[n + 1];
    int[] left = new int[n + 1];
    int[] right = new int[n + 1];
    key[1] = a[0];
    for (int i = 2; i <= n; i++) {
        key[i] = a[i - 1];
        int node = 1;
        while (true) {
            if (key[i] < key[node]) {
                if (left[node] == 0) {
                    left[node] = i;
                    break;
                }
                node = left[node];
            } else {
                if (right[node] == 0) {
                    right[node] = i;
                    break;
                }
                node = right[node];
            }
        }
    }
    readInOrder(key, left, right, 1, a);
}

/** Walks the tree in order with an explicit stack, because a tree can be n levels deep. */
private static void readInOrder(int[] key, int[] left, int[] right, int root, int[] out) {
    int[] stack = new int[out.length + 1];
    int top = 0;
    int node = root;
    int k = 0;
    while (node != 0 || top > 0) {
        while (node != 0) {
            stack[top] = node;
            top++;
            node = left[node];
        }
        top--;
        node = stack[top];
        out[k] = key[node];
        k++;
        node = right[node];
    }
}

