/** Builds a Cartesian tree in O(n), then pulls items out with a heap of candidates. */
static void cartesian(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int[] key = new int[n + 1];
    int[] left = new int[n + 1];
    int[] right = new int[n + 1];
    int[] spine = new int[n + 1];
    int top = 0;
    for (int i = 1; i <= n; i++) {
        key[i] = a[i - 1];
        int last = 0;
        while (top > 0 && key[spine[top - 1]] > key[i]) {
            top--;
            last = spine[top];
        }
        left[i] = last;
        if (top > 0) {
            right[spine[top - 1]] = i;
        }
        spine[top] = i;
        top++;
    }
    int[] heap = new int[n + 1];
    heap[0] = spine[0];
    int count = 1;
    for (int k = 0; k < n; k++) {
        int node = heap[0];
        a[k] = key[node];
        count--;
        heap[0] = heap[count];
        candidateDown(heap, key, count);
        if (left[node] != 0) {
            candidateUp(heap, key, count, left[node]);
            count++;
        }
        if (right[node] != 0) {
            candidateUp(heap, key, count, right[node]);
            count++;
        }
    }
}

