private static void candidateDown(int[] heap, int[] key, int count) {
    int i = 0;
    while (true) {
        int child = 2 * i + 1;
        if (child >= count) {
            return;
        }
        if (child + 1 < count && key[heap[child + 1]] < key[heap[child]]) {
            child++;
        }
        if (key[heap[child]] >= key[heap[i]]) {
            return;
        }
        swap(heap, i, child);
        i = child;
    }
