static void pigeonhole(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int min = minOf(a);
    int[] hole = new int[maxOf(a) - min + 1];
    int[] next = new int[n + 1];
    int[] item = copy(a);
    for (int i = n - 1; i >= 0; i--) {
        int h = item[i] - min;
        next[i + 1] = hole[h];
        hole[h] = i + 1;
    }
    int k = 0;
    for (int h = 0; h < hole.length; h++) {
        for (int node = hole[h]; node != 0; node = next[node]) {
            a[k] = item[node - 1];
            k++;
        }
    }
}

