static void flash(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int min = a[0];
    int top = 0;
    for (int i = 1; i < n; i++) {
        if (a[i] < min) {
            min = a[i];
        }
        if (a[i] > a[top]) {
            top = i;
        }
    }
    if (a[top] == min) {
        return;
    }
    int classes = Math.max(2, (int) (0.43 * n));
    double scale = (double) (classes - 1) / (a[top] - min);
    int[] end = new int[classes];
    for (int i = 0; i < n; i++) {
        end[(int) (scale * (a[i] - min))]++;
    }
    for (int c = 1; c < classes; c++) {
        end[c] += end[c - 1];
    }
    swap(a, top, 0);
    // Follow cycles: each item goes to the end of its class and bumps the one there.
    int moves = 0;
    int j = 0;
    int c = classes - 1;
    while (moves < n - 1) {
        while (j > end[c] - 1) {
            j++;
            c = (int) (scale * (a[j] - min));
        }
        int flying = a[j];
        while (j != end[c]) {
            c = (int) (scale * (flying - min));
            int held = a[end[c] - 1];
            a[end[c] - 1] = flying;
            flying = held;
            end[c]--;
            moves++;
        }
    }
    insertionRange(a, 0, n - 1);
}

