    int[] hits = new int[n];
    for (int i = 0; i < n; i++) {
        hits[(int) ((a[i] - min) * scale)]++;
    }
    int[] start = new int[n];
    int running = 0;
    for (int k = 0; k < n; k++) {
        start[k] = running;
        running += hits[k];
    }
    int[] out = new int[n];
    int[] placed = new int[n];
    for (int i = 0; i < n; i++) {
        int x = a[i];
        int k = (int) ((x - min) * scale);
        int first = start[k];
        int pos = first + placed[k];
        placed[k]++;
        while (pos > first && out[pos - 1] > x) {
            out[pos] = out[pos - 1];
            pos--;
        }
        out[pos] = x;
    }
    arraycopy(out, 0, a, 0, n);
}

