/** Each value is a row of beads on rods. Let them fall, then read the rows back. */
static void bead(int[] a) {
    int n = a.length;
    if (n < 2) {
        return;
    }
    int[] rod = new int[maxOf(a)];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < a[i]; j++) {
            rod[j]++;
        }
    }
    for (int row = 0; row < n; row++) {
        int beads = 0;
        while (beads < rod.length && rod[beads] > row) {
            beads++;
        }
        a[n - 1 - row] = beads;
    }
}

