                    if ((i + j) >> (level + 1) == (i + j + k) >> (level + 1)) {
                        compareExchange(a, i + j, i + j + k);
                    }
                }
            }
        }
    }
}

function compareExchange(a, i, j) {
    if (a[i] > a[j]) {
        swap(a, i, j);
    }
}

