static void stooge(int[] a) {
    if (a.length > 1) {
        stoogeRange(a, 0, a.length - 1);
    }
}

private static void stoogeRange(int[] a, int lo, int hi) {
    if (a[lo] > a[hi]) {
        swap(a, lo, hi);
    }
    if (hi - lo + 1 > 2) {
        int third = div(hi - lo + 1, 3);
        stoogeRange(a, lo, hi - third);
        stoogeRange(a, lo + third, hi);
        stoogeRange(a, lo, hi - third);
    }
}

