slow.java:
static void slow(int[] a) {
    slowRange(a, 0, a.length - 1);
}

/** "Multiply and surrender": the opposite of divide and conquer. */
private static void slowRange(int[] a, int lo, int hi) {
    if (lo >= hi) {
        return;
    }
    int mid = (lo + hi) >>> 1;
    slowRange(a, lo, mid);
    slowRange(a, mid + 1, hi);
    if (a[hi] < a[mid]) {
        swap(a, hi, mid);
    }
    slowRange(a, lo, hi - 1);
}

