static void bogo(int[] a) {
    int seed = -1640531527;
    while (!isSorted(a)) {
        for (int i = a.length - 1; i > 0; i--) {
            seed = nextRandom(seed);
            swap(a, i, (seed >>> 1) % (i + 1));
        }
    }
}

